const nav=document.querySelector('header>nav[aria-label="Navegación principal"]');
if(nav){
 const home=path=>['/','/index','/index.html'].includes(path),canonical=path=>path.replace(/\.html$/,'').replace(/\/$/,'')||'/';
 function mark(){let match=null;for(const link of nav.querySelectorAll('a')){const url=new URL(link.href,location.href);if(url.origin!==location.origin)continue;const same=canonical(url.pathname)===canonical(location.pathname)||(home(url.pathname)&&home(location.pathname));if(same&&((home(location.pathname)&&url.hash===location.hash&&!!url.hash)||(!home(location.pathname)&&(!url.hash||url.hash===location.hash))))match=link;if(canonical(location.pathname)==='/galeria'&&url.hash==='#galeria')match=link;}for(const link of nav.querySelectorAll('a')){if(link===match)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');}}
 function jump(){if(!home(location.pathname)||!location.hash)return;const target=document.getElementById(location.hash.slice(1));if(target){target.scrollIntoView({behavior:'instant',block:'start'});mark();}}
 nav.addEventListener('click',event=>{const link=event.target.closest('a');if(!link||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey||link.target==='_blank')return;const url=new URL(link.href,location.href);if(url.origin!==location.origin)return;if(home(url.pathname)&&home(location.pathname)&&url.hash){const target=document.getElementById(url.hash.slice(1));if(!target)return;event.preventDefault();history.pushState(null,'',url.hash);mark();target.scrollIntoView({behavior:'instant',block:'start'});target.setAttribute('tabindex','-1');target.focus({preventScroll:true});}});
 window.addEventListener('hashchange',()=>{mark();jump();});window.addEventListener('popstate',()=>{mark();jump();});mark();jump();window.addEventListener('load',jump,{once:true});
}
